(1915592, 263228, 42100, '<td valign="top">This sunset is very colorful and popular.  But with the number of sunset photos out there us viewers become jaded and look for that something extra in the composition.</td>', 'This sunset is very colorful and popular.  But with the number of sunset photos out there us viewers become jaded and look for that something extra in the composition.', '2005-12-02 09:21:47.000000', NULL, 1),
(1915593, 260833, 42492, '<td valign="top">nice</td>', 'nice', '2005-12-02 09:21:49.000000', NULL, 1),
