(1915826, 263629, 37961, '<td valign="top">Nice clear candid. Crop and composition is great.</td>', 'Nice clear candid. Crop and composition is great.', '2005-12-02 11:04:23.000000', NULL, 1),
(1915828, 258685, 39349, '<td valign="top">WOW! Tack sharp DOF and amazing color tones. Beautifully captured sunset without being blown out. 10 for a stunning capture, and very well done!</td>', 'WOW! Tack sharp DOF and amazing color tones. Beautifully captured sunset without being blown out. 10 for a stunning capture, and very well done!', '2005-12-02 11:04:34.000000', NULL, 1),
