(1915833, 264035, 37961, '<td valign="top">Good motion blur of the train. Dad and son really add the visual interest here. Nice.</td>', 'Good motion blur of the train. Dad and son really add the visual interest here. Nice.', '2005-12-02 11:05:49.000000', NULL, 1),
(1915839, 264027, 37961, '<td valign="top">Is that really a star?  Colors and clouds make this a very beautiful picture.</td>', 'Is that really a star?  Colors and clouds make this a very beautiful picture.', '2005-12-02 11:07:48.000000', NULL, 1),
