INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1916977, 258915, 34013, '<td valign="top">love the design element and the grunge effect. works well!</td>', 'love the design element and the grunge effect. works well!', '2005-12-02 17:45:33.000000', NULL, 1),
(1916979, 261617, 34013, '<td valign="top">cool shot.</td>', 'cool shot.', '2005-12-02 17:46:36.000000', NULL, 1),
(1916980, 261275, 34013, '<td valign="top">amazing clarity and excellent color saturation! 9</td>', 'amazing clarity and excellent color saturation! 9', '2005-12-02 17:47:30.000000', NULL, 1),
(1916981, 264203, 34013, '<td valign="top">how amazingingly beautiful. rich, vivid colors! nice work.</td>', 'how amazingingly beautiful. rich, vivid colors! nice work.', '2005-12-02 17:48:54.000000', NULL, 1),
(1916985, 264086, 34013, '<td valign="top">wow, this shot is awesome! i love the lines and the contrast of the man/rock vs the landscapes in varying degrees of gray in the bg. really really awesome shot. 10 from me!</td>', 'wow, this shot is awesome! i love the lines and the contrast of the man/rock vs the landscapes in varying degrees of gray in the bg. really really awesome shot. 10 from me!', '2005-12-02 17:50:32.000000', NULL, 1),
(1916986, 264177, 37544, '<td valign="top">wow this is wonderful!</td>', 'wow this is wonderful!', '2005-12-02 17:50:43.000000', NULL, 1),
(1916987, 264129, 34013, '<td valign="top">lol! too clever~and hilarious</td>', 'lol! too clever~and hilarious', '2005-12-02 17:50:52.000000', NULL, 1),
(1916989, 264004, 34013, '<td valign="top">beautiful shot!</td>', 'beautiful shot!', '2005-12-02 17:51:09.000000', NULL, 1),
(1916993, 260078, 34013, '<td valign="top">geez!!! AMAZING, and right on the money. wow...i''m sorry i''m just blown away! 10 from me for sure!!</td>', 'geez!!! AMAZING, and right on the money. wow...i''m sorry i''m just blown away! 10 from me for sure!!', '2005-12-02 17:52:30.000000', NULL, 1),
(1916994, 261658, 25890, '<td valign="top">There''s obviously a truly beautiful photograph to be made at this location. However, this one is not it, I''m afraid. I think that the tree is an intruder obstructing the grander view behind it. The completely black blob at the bottom-left corner weakens the composition too. As for the exposure, and this is only a matter of personal taste, I would have tried to darken the sky a little bit while still retaining some more detail on the foreground rocks by using a soft egded gradual neutral density filter, or certain exposure blending techniques (I believe it''s legal in advanced editing to get multiple frames with different exposure adjustments from a single RAW negative and blend them in editing software).</td>', 'There''s obviously a truly beautiful photograph to be made at this location. However, this one is not it, I''m afraid. I think that the tree is an intruder obstructing the grander view behind it. The completely black blob at the bottom-left corner weakens the composition too. As for the exposure, and this is only a matter of personal taste, I would have tried to darken the sky a little bit while still retaining some more detail on the foreground rocks by using a soft egded gradual neutral density filter, or certain exposure blending techniques (I believe it''s legal in advanced editing to get multiple frames with different exposure adjustments from a single RAW negative and blend them in editing software).', '2005-12-02 17:52:54.000000', NULL, 1),
(1916995, 261908, 34013, '<td valign="top">beautiful, beautiful beautiful shot. the colors are amazing. also the framing is very well done.</td>', 'beautiful, beautiful beautiful shot. the colors are amazing. also the framing is very well done.', '2005-12-02 17:54:05.000000', NULL, 1),
(1917001, 256455, 34013, '<td valign="top">i like the color saturation, its interesting. good shot!</td>', 'i like the color saturation, its interesting. good shot!', '2005-12-02 17:57:41.000000', NULL, 1),
(1917003, 261967, 34013, '<td valign="top">gorgeous shot!!</td>', 'gorgeous shot!!', '2005-12-02 17:59:50.000000', NULL, 1),
(1917012, 262055, 29906, '<td valign="top">Very interesting pose, 9</td>', 'Very interesting pose, 9', '2005-12-02 18:05:20.000000', NULL, 1),
