(1920785, 263436, 42638, '<td valign="top">Wow, great picture. Love the light reflected on the detailed water droplets. Nice!</td>', 'Wow, great picture. Love the light reflected on the detailed water droplets. Nice!', '2005-12-04 10:49:03.000000', NULL, 1),
(1920786, 264004, 42638, '<td valign="top">Wow, Beautiful picture. The clouds seem to be singing praises too. Wonderful colors.</td>', 'Wow, Beautiful picture. The clouds seem to be singing praises too. Wonderful colors.', '2005-12-04 10:49:59.000000', NULL, 1),
