(1920798, 260078, 42638, '<td valign="top">Wow, fantastic color and lines. Wonderful lighting making for a great picture.</td>', 'Wow, fantastic color and lines. Wonderful lighting making for a great picture.', '2005-12-04 10:53:49.000000', NULL, 1),
(1920802, 263982, 42638, '<td valign="top">HA!  Great title, good sense of humor! It really moves this picture.</td>', 'HA!  Great title, good sense of humor! It really moves this picture.', '2005-12-04 10:56:30.000000', NULL, 1),
