(1921483, 260489, 43844, '<td valign="top">What makes this picture special is that I''m pretty sure who took it.  A unique and consistent style combined with rich compositions sets you apart from the rest.  Nice job.</td>', 'What makes this picture special is that I''m pretty sure who took it.  A unique and consistent style combined with rich compositions sets you apart from the rest.  Nice job.', '2005-12-04 17:47:35.000000', NULL, 1),
(1921487, 263455, 36999, '<td valign="top">nice composition, better/different lighting could improve the shot</td>', 'nice composition, better/different lighting could improve the shot', '2005-12-04 17:48:07.000000', NULL, 1),
(1921488, 264115, 43844, '<td valign="top">I like the blue to red flow of this shot but it seems a little flat, 2-dimensional.</td>', 'I like the blue to red flow of this shot but it seems a little flat, 2-dimensional.', '2005-12-04 17:48:24.000000', NULL, 1),
(1921489, 261572, 43844, '<td valign="top">Sharp.</td>', 'Sharp.', '2005-12-04 17:48:38.000000', NULL, 1),
