(1921504, 262579, 43844, '<td valign="top">Great look on the dog''s face.  Wish the couch wasn''t in the way.</td>', 'Great look on the dog''s face.  Wish the couch wasn''t in the way.', '2005-12-04 17:55:06.000000', NULL, 1),
(1921506, 256687, 43844, '<td valign="top">Well done.  Must have been fun to shoot.</td>', 'Well done.  Must have been fun to shoot.', '2005-12-04 17:56:17.000000', NULL, 1),
(1921507, 263751, 43844, '<td valign="top">Beautiful setting.  Wish the colors had more punch.  Well done.</td>', 'Beautiful setting.  Wish the colors had more punch.  Well done.', '2005-12-04 17:56:41.000000', NULL, 1),
(1921508, 261316, 43844, '<td valign="top">What makes this shot interesting is the fact that the ivy inside the truck hasn''t shed its leafs.</td>', 'What makes this shot interesting is the fact that the ivy inside the truck hasn''t shed its leafs.', '2005-12-04 17:58:21.000000', NULL, 1),
(1921509, 263392, 43844, '<td valign="top">I wish I could do that, or at least live there.  Beautiful.</td>', 'I wish I could do that, or at least live there.  Beautiful.', '2005-12-04 17:59:11.000000', NULL, 1),
(1921511, 257484, 43844, '<td valign="top">Nice fish.  Wished the colors popped a bit more.  Good job.</td>', 'Nice fish.  Wished the colors popped a bit more.  Good job.', '2005-12-04 17:59:51.000000', NULL, 1),
