(1921521, 256912, 43844, '<td valign="top">Beautifully eerie.  If feels like I''m in the picture.</td>', 'Beautifully eerie.  If feels like I''m in the picture.', '2005-12-04 18:05:25.000000', NULL, 1),
(1921524, 264173, 43844, '<td valign="top">Remarkable.  The layers are each characterized by a distinct and different texture, shade and color.  One of the best in show for sure.</td>', 'Remarkable.  The layers are each characterized by a distinct and different texture, shade and color.  One of the best in show for sure.', '2005-12-04 18:06:35.000000', NULL, 1),
