(1921530, 263974, 43844, '<td valign="top">Looks like fire.  Great sunset.</td>', 'Looks like fire.  Great sunset.', '2005-12-04 18:07:49.000000', NULL, 1),
(1921532, 259861, 43844, '<td valign="top">Love the pose, the silvery water and the crisp action shot.  Nicely done.</td>', 'Love the pose, the silvery water and the crisp action shot.  Nicely done.', '2005-12-04 18:08:25.000000', NULL, 1),
