(1922110, 256413, 24846, '<td valign="top">Good luck on this study.</td>', 'Good luck on this study.', '2005-12-04 22:19:43.000000', NULL, 1),
(1922114, 262310, 43437, '<td valign="top">Such character.  I like how you didnt try to smooth anything out, and the light just hilights every crease.</td>', 'Such character.  I like how you didnt try to smooth anything out, and the light just hilights every crease.', '2005-12-04 22:20:12.000000', NULL, 1),
