(1930945, 258117, 11499, '<td valign="top">Me encanta! realmente parece que esta posando...</td>', 'Me encanta! realmente parece que esta posando...', '2005-12-07 08:13:35.000000', NULL, 1),
(1930988, 263505, 42374, '<td valign="top">Perfect composition.</td>', 'Perfect composition.', '2005-12-07 08:27:55.000000', NULL, 1),
(1931000, 263970, 42374, '<td valign="top">Bit too much fog but interesting.</td>', 'Bit too much fog but interesting.', '2005-12-07 08:32:56.000000', NULL, 1),
(1931043, 263833, 37334, '<td valign="top">I could look at this for hours.</td>', 'I could look at this for hours.', '2005-12-07 08:46:59.000000', NULL, 1),
