(1931061, 261955, 37334, '<td valign="top">Gorgeous!</td>', 'Gorgeous!', '2005-12-07 08:55:43.000000', NULL, 1),
(1931077, 260082, 24111, '<td valign="top">took me a while to figure out the dog, but this is very cool!</td>', 'took me a while to figure out the dog, but this is very cool!', '2005-12-07 09:05:31.000000', NULL, 1),
(1931088, 261658, 32321, '<td valign="top">I really like what you did with this picture. I''m not usually a B&amp;W person, but I gave this my top score. Good luck</td>', 'I really like what you did with this picture. I''m not usually a B&W person, but I gave this my top score. Good luck', '2005-12-07 09:12:53.000000', NULL, 1),
(1931093, 264086, 32321, '<td valign="top">Excellent shot. I really like the different ridge lines and the placement of the person. Good luck</td>', 'Excellent shot. I really like the different ridge lines and the placement of the person. Good luck', '2005-12-07 09:14:29.000000', NULL, 1),
(1931097, 263872, 32321, '<td valign="top">Excellent capture of the eyes and face expresion. Really well titled. Good luck</td>', 'Excellent capture of the eyes and face expresion. Really well titled. Good luck', '2005-12-07 09:16:06.000000', NULL, 1),
(1931100, 263957, 32321, '<td valign="top">I like the northern lights against the back ridge. Nice contrast, but I find the white gate very distracting.</td>', 'I like the northern lights against the back ridge. Nice contrast, but I find the white gate very distracting.', '2005-12-07 09:18:48.000000', NULL, 1),
(1931110, 260010, 32321, '<td valign="top">Nice capture of colours and mood. May have been more interesting with a person waiting inside.</td>', 'Nice capture of colours and mood. May have been more interesting with a person waiting inside.', '2005-12-07 09:22:11.000000', NULL, 1),
(1931115, 263854, 32321, '<td valign="top">Excellent shot. The colours and detail are great. Are they crazy?</td>', 'Excellent shot. The colours and detail are great. Are they crazy?', '2005-12-07 09:24:58.000000', NULL, 1),
(1931119, 263943, 32321, '<td valign="top">Nice capture of the eyes and face. Good luck</td>', 'Nice capture of the eyes and face. Good luck', '2005-12-07 09:26:52.000000', NULL, 1),
(1931128, 263654, 32321, '<td valign="top">Find there is not enough contrast between the sky and the person. Over all the picture is very dark except where the sun set is.</td>', 'Find there is not enough contrast between the sky and the person. Over all the picture is very dark except where the sun set is.', '2005-12-07 09:29:54.000000', NULL, 1),
(1931133, 261371, 29474, '<td valign="top">Like the way the cloud formations follow the wave lines.</td>', 'Like the way the cloud formations follow the wave lines.', '2005-12-07 09:31:51.000000', NULL, 1),
(1931136, 257178, 32321, '<td valign="top">Found the different inages distracting. Took me a while to figure out what you did.</td>', 'Found the different inages distracting. Took me a while to figure out what you did.', '2005-12-07 09:32:39.000000', NULL, 1),
(1931143, 262909, 32321, '<td valign="top">Great capture, but I find it a bit over processed.</td>', 'Great capture, but I find it a bit over processed.', '2005-12-07 09:35:35.000000', NULL, 1),
(1931169, 260267, 29474, '<td valign="top">This is a very simple but sensual picture. And the closed eyes make it work.</td>', 'This is a very simple but sensual picture. And the closed eyes make it work.', '2005-12-07 09:47:18.000000', NULL, 1),
(1931179, 263970, 3548, '<td valign="top">Absolutely, stunningly, breath-takingly beautiful!</td>', 'Absolutely, stunningly, breath-takingly beautiful!', '2005-12-07 09:52:12.000000', NULL, 1),
(1931261, 264132, 3548, '<td valign="top">Wonderful shot!</td>', 'Wonderful shot!', '2005-12-07 10:31:02.000000', NULL, 1),
(1931347, 261967, 10390, '<td valign="top">This is one of the best in this challenge, very well done, mayge the white in the eyes is a little bit too bright. Well done!</td>', 'This is one of the best in this challenge, very well done, mayge the white in the eyes is a little bit too bright. Well done!', '2005-12-07 10:55:43.000000', NULL, 1),
(1931350, 257541, 28471, '<td valign="top">The highkey lighting works well here.  Most of the time high key looks washed out but this nicely done.</td>', 'The highkey lighting works well here.  Most of the time high key looks washed out but this nicely done.', '2005-12-07 10:55:50.000000', NULL, 1),
(1931361, 261963, 10390, '<td valign="top">Beautiful photo, there is a little bit too much red/magenta tone in it, the shadow at the right distracts a little.  Otherwise this is very nice.</td>', 'Beautiful photo, there is a little bit too much red/magenta tone in it, the shadow at the right distracts a little.  Otherwise this is very nice.', '2005-12-07 10:58:16.000000', NULL, 1),
(1931366, 262843, 10390, '<td valign="top">the white is too white and the blue is too blue. I think you''ve went to far with the editing. Otherwise this is well framed and looks nice, but the editing drags it a little down.</td>', 'the white is too white and the blue is too blue. I think you''ve went to far with the editing. Otherwise this is well framed and looks nice, but the editing drags it a little down.', '2005-12-07 11:00:08.000000', NULL, 1),
(1931374, 260010, 10390, '<td valign="top">jeg tænker din foto skal ikke har Ribbon... My Danish is bad, I think this is creative but isn''t interesting enough.</td>', 'jeg tænker din foto skal ikke har Ribbon... My Danish is bad, I think this is creative but isn''t interesting enough.', '2005-12-07 11:04:13.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1931415, 264131, 10390, '<td valign="top">Very nice and creative, I like the color tone a lot and I use a similar one frequently in my photos.</td>', 'Very nice and creative, I like the color tone a lot and I use a similar one frequently in my photos.', '2005-12-07 11:18:51.000000', NULL, 1),
(1931442, 263384, 8624, '<td valign="top">wow. that''s quite a flock! great find.</td>', 'wow. that''s quite a flock! great find.', '2005-12-07 11:26:21.000000', NULL, 1),
(1931450, 255145, 10390, '<td valign="top">Great phtoo, the plane is perfectly positioned inside the frame, one of the best in this challenge.</td>', 'Great phtoo, the plane is perfectly positioned inside the frame, one of the best in this challenge.', '2005-12-07 11:26:58.000000', NULL, 1),
(1931481, 264090, 10390, '<td valign="top">Simple and good photo, well framed and good use of bokeh.</td>', 'Simple and good photo, well framed and good use of bokeh.', '2005-12-07 11:32:42.000000', NULL, 1),
(1931493, 264188, 29269, '<td valign="top">Oh, size... but you know that by now. The lightbulb in teh top left corner is in focus, but it hardly occupies enough of the image to complement the huge area of OOF lights. The idea for the study is good, and I am not scoring this low just because it is blurry - rather because it failed to use the blur in a eye-pleasing manner (at least in my opinion).</td>', 'Oh, size... but you know that by now. The lightbulb in teh top left corner is in focus, but it hardly occupies enough of the image to complement the huge area of OOF lights. The idea for the study is good, and I am not scoring this low just because it is blurry - rather because it failed to use the blur in a eye-pleasing manner (at least in my opinion).', '2005-12-07 11:35:15.000000', NULL, 1),
(1931495, 264004, 10390, '<td valign="top">strange pastel-colors in the sky, this photo needs to be a little brighter or even darker. In whole, with the editing the photo doesn''t appeal to me, the editing drags it down.</td>', 'strange pastel-colors in the sky, this photo needs to be a little brighter or even darker. In whole, with the editing the photo doesn''t appeal to me, the editing drags it down.', '2005-12-07 11:35:25.000000', NULL, 1),
(1931512, 261684, 29269, '<td valign="top">This one would have been exceptional if you, for example, told the kid in green shirt with a gree baloon to stand facing you and stand still for a second. That way, you would have gotten something - motion and enjoyment in the background, and crisp (at least somewhat) standing kid not participating. Just an idea and an attempt to offer constuctive criticism and a reason why I scored this with 3.</td>', 'This one would have been exceptional if you, for example, told the kid in green shirt with a gree baloon to stand facing you and stand still for a second. That way, you would have gotten something - motion and enjoyment in the background, and crisp (at least somewhat) standing kid not participating. Just an idea and an attempt to offer constuctive criticism and a reason why I scored this with 3.', '2005-12-07 11:38:02.000000', NULL, 1),
(1931524, 263145, 37961, '<td valign="top">This is a really interesting photo. Almost like an abstract painting.  Love the angle and the light...Wow.</td>', 'This is a really interesting photo. Almost like an abstract painting.  Love the angle and the light...Wow.', '2005-12-07 11:41:01.000000', NULL, 1),
(1931528, 260848, 10390, '<td valign="top">The editing is way too overdone in this photo for my taste, but I''ll give you a credit for trying to do something different though.</td>', 'The editing is way too overdone in this photo for my taste, but I''ll give you a credit for trying to do something different though.', '2005-12-07 11:42:02.000000', NULL, 1),
(1931537, 256358, 37961, '<td valign="top">Im a sucker for a good dog portrait. But I feel this photo needs more sharpness and saturation of color. Composition and posing are good. Lighting seems perfect. Love the way the leaves match his coloring. Nice.</td>', 'Im a sucker for a good dog portrait. But I feel this photo needs more sharpness and saturation of color. Composition and posing are good. Lighting seems perfect. Love the way the leaves match his coloring. Nice.', '2005-12-07 11:43:48.000000', NULL, 1),
(1931549, 264051, 33679, '<td valign="top">Nylon jibbý!<br/> <br/>Þessi mynd væri miklu betri ef Steinunn væri í fókus en ekki Klara.</td>', 'Nylon jibbý! Þessi mynd væri miklu betri ef Steinunn væri í fókus en ekki Klara.', '2005-12-07 11:45:58.000000', NULL, 1),
(1931551, 262857, 37961, '<td valign="top">Wow, great wingspan. I''ve yet to be able to get good bird in flight photos. Nice!</td>', 'Wow, great wingspan. I''ve yet to be able to get good bird in flight photos. Nice!', '2005-12-07 11:46:15.000000', NULL, 1),
(1931593, 263034, 37961, '<td valign="top">Wow that look so cold. Love the long exposure on the water.</td>', 'Wow that look so cold. Love the long exposure on the water.', '2005-12-07 11:59:06.000000', NULL, 1),
